template<typename T>
struct Vector {
    T* data; size_t size;
    T operator[](size_t i) const { return data[i]; }

    // Evaluation point: Compiler fuses loops here
    template<typename Expr>
    Vector& operator=(const Expr& expr) {
        for (size_t i = 0; i < size; ++i) data[i] = expr[i];
        return *this;
    }
};

// Expression Node (Represents deferred A + B)
template<typename L, typename R>
struct VAddExpr {
    const L& l; const R& r;
    auto operator[](size_t i) const { return l[i] + r[i]; }
};

// Deferred Operation: Returns Expression Node, NOT a resulting Vector
template<typename L, typename R>
VAddExpr<L, R> operator+(const L& l, const R& r) {
    return { l, r };
}

// Usage: Vector C = A + B * 2.0; (Single fused loop upon assignment)
// The type of (A + B) is VAddExpr<Vector, Vector>
// The type of C = ... is evaluated by Vector::operator=
